// Every rule of every grammar the Prism reads by is matched as its
// specification writes it (app/specs/grammar/spec.json, generated by
// tools/standards/grammar.py from the pinned RFCs). For each rule the
// generator derives, from the grammar itself, the shortest field or message
// that goes through it (its witness); the reader must match that whole text by
// its rule and the rule's own part of it by the rule alone. The published
// examples (test/oracle/corpus.json) are then read field by field, each by its
// own rule, and test/oracle/read.test.mjs holds what they mean to the
// reference reader.
// The same grammar compiled into the Prism (app/src/PrismGrammarMail, read by
// Foundation.Abnf, built as the grammar-mail guest) answers every witness with
// the derivation this matcher gives.
// usage: node --test test/standards/grammar.test.mjs
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { abnf } from "../../site/read/abnf.mjs";
import { fieldsOf, readField, rulesOf } from "../../site/read/mail.mjs";
import { GUESTS, openGuest } from "../../site/read/guest.mjs";

const spec = JSON.parse(readFileSync("app/specs/grammar/spec.json", "utf8"));
const { corpus } = JSON.parse(readFileSync("test/oracle/corpus.json", "utf8"));

test("each grammar is its pinned specifications' own, as tools/standards/grammar.py takes it", () => {
  const run = spawnSync("python3", ["-I", "tools/standards/grammar.py", "--check", "--cache", join(tmpdir(), "prism-grammar")], { encoding: "utf8" });
  assert.equal(run.status, 0, run.stderr || run.stdout);
  const vectors = spawnSync("node", ["tools/standards/vectors.mjs", "--check"], { encoding: "utf8" });
  assert.equal(vectors.status, 0, vectors.stderr || vectors.stdout);
});

for (const g of spec.grammars) {
  const table = (await import(`../../${g.out}`)).default;
  const engine = abnf(table);
  const { witnesses } = JSON.parse(readFileSync(g.witnesses, "utf8"));

  test(`${g.key}: every rule of the grammar has a witness, and only rules of the grammar do`, () => {
    assert.deepEqual(Object.keys(witnesses).sort(), Object.keys(table.rules).sort());
  });

  test(`${g.key}: each rule matches its witness, as a whole and alone`, () => {
    const missed = [];
    for (const [rule, w] of Object.entries(witnesses)) {
      const own = Array.from(w.text).slice(w.start, w.end).join("");
      if (!engine.match(w.context, w.text)) missed.push(`${rule}: ${w.context} does not match ${JSON.stringify(w.text)}`);
      else if (!engine.match(rule, own)) missed.push(`${rule} does not match its own ${JSON.stringify(own)}`);
    }
    assert.deepEqual(missed, []);
  });

  if (g.headers) test(`${g.key}: each field's witness is read by one of its own rules`, () => {
    const missed = [];
    for (const [name, rules] of Object.entries(table.fields)) {
      for (const rule of rules) {
        const field = readField(witnesses[rule].text);
        if (field?.name !== name || !rules.includes(field.rule)) missed.push(`${name}: ${JSON.stringify(witnesses[rule].text)} read as ${field?.rule}`);
      }
    }
    assert.deepEqual(missed, []);
  });

  if (g.headers) test(`${g.key}: each published example's fields are read by their own rules`, () => {
    const examples = corpus.filter((c) => c.kind === "message");
    assert.ok(examples.length > 20);
    const used = new Set();
    for (const c of examples) {
      const fields = fieldsOf(c.raw);
      for (const f of fields) {
        const own = table.fields[f.name];
        if (own) assert.ok(own.includes(f.rule), `${c.id}: ${f.name} read as ${f.rule}, not by ${own.join(" or ")}`);
        else assert.ok(f.rule === "optional-field" || f.rule === "obs-optional", `${c.id}: ${f.name} read as ${f.rule}`);
      }
      rulesOf(fields).forEach((r) => used.add(r));
    }
    console.log(`${g.key}: the published examples go through ${used.size} of ${Object.keys(table.rules).length} rules; the witnesses through all of them`);
  });
}

// The MIME specifications' own example fields (RFC 2045, 2046, 2183, 2231, their
// verified errata applied), each read as Python's email package reads it, or,
// where that finds it defective, not read as a MIME field at all.
test("each MIME example field reads as the reference reader reads it", async () => {
  const { contentType, disposition, readField } = await import("../../site/read/mail.mjs");
  const { examples } = JSON.parse(readFileSync("test/standards/mail.examples.json", "utf8"));
  assert.ok(examples.length >= 30);
  const missed = [];
  for (const ex of examples) {
    const field = readField(ex.text);
    const own = field.name === "content-type" ? "content" : "disposition";
    if (ex.expect.defective) {
      if (field.rule === own) missed.push(`${ex.id}: the reference finds it defective, the grammar reads it as ${own}`);
      continue;
    }
    const got = field.name === "content-type" ? contentType([field]) : disposition([field]);
    const want = { type: ex.expect.type, params: ex.expect.params };
    if (JSON.stringify({ type: got.type, params: got.params }) !== JSON.stringify(want) && !(JSON.stringify(Object.entries(got.params).sort()) === JSON.stringify(Object.entries(want.params).sort()) && got.type === want.type)) missed.push(`${ex.id}: ${JSON.stringify({ type: got.type, params: got.params })}, not ${JSON.stringify(want)}`);
  }
  assert.deepEqual(missed, []);
});

// The Prism's own matcher (LexLean, Foundation.Abnf) against this one, witness by witness.
for (const g of spec.grammars.filter((x) => x.module)) {
  const table = (await import(`../../${g.out}`)).default;
  const engine = abnf(table);
  const { witnesses } = JSON.parse(readFileSync(g.witnesses, "utf8"));
  const names = Object.keys(table.rules).sort();
  const index = Object.fromEntries(names.map((n, i) => [n, i]));
  const id = `grammar-${g.key}`;
  test(`${g.key}: the grammar compiled into the Prism derives every witness as this matcher does`, async () => {
    const guest = GUESTS[id];
    const ask = await openGuest(readFileSync(new URL(`../../site/read/${guest.path}`, import.meta.url)), guest.sha256);
    const encoder = new TextEncoder();
    const octets = (text) => { const at = [0]; for (const c of Array.from(text)) at.push(at.at(-1) + encoder.encode(c).length); return at; };
    const spans = (tree, at, depth = 0, out = []) => {
      out.push(`${index[tree.rule]},${at[tree.start]},${at[tree.end]},${depth}`);
      for (const kid of tree.kids) spans(kid, at, depth + 1, out);
      return out;
    };
    const cases = Object.entries(witnesses).flatMap(([rule, w]) => [[w.context, w.text], [rule, Array.from(w.text).slice(w.start, w.end).join("")]]);
    const differ = [];
    const started = performance.now();
    for (const [rule, text] of cases) {
      const tree = engine.match(rule, text);
      const want = tree ? spans(tree, octets(text)).join(" ") : "none";
      const got = await ask(`${index[rule]} ${text}`);
      if (got !== want) differ.push(`${rule} ${JSON.stringify(text)}: ${got.slice(0, 120)}`);
    }
    console.log(`${g.key}: the Prism's matcher answered ${cases.length} witnesses in ${Math.round(performance.now() - started)} ms`);
    assert.deepEqual(differ, []);
  });
}
